parameters.query:
select
  (select json_agg(r) from retailers r where activo) as retailers,
  (select json_agg(m) from marcas m where activo)    as marcas;

parameters.jsCode:
// Nodo "Generar URLs" — arma una búsqueda por cada (cadena × marca × página).
// Entrada: 1 item con { retailers: [...], marcas: [...] } desde Supabase.
const cfg = $input.first().json;
const retailers = cfg.retailers || [];
const marcas = cfg.marcas || [];

const PAGINAS_VTEX = 3;     // 3 páginas × 50 = hasta 150 productos por marca y cadena
const POR_PAGINA_VTEX = 50; // máximo que acepta VTEX
const PAGINAS_COTO = 2;
const POR_PAGINA_COTO = 60;

const fecha = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Argentina/Buenos_Aires' }).format(new Date());

const out = [];
for (const r of retailers) {
  for (const m of marcas) {
    const termino = encodeURIComponent(m.termino);
    if (r.plataforma === 'vtex') {
      for (let p = 0; p < PAGINAS_VTEX; p++) {
        const desde = p * POR_PAGINA_VTEX;
        out.push({ json: {
          url: `https://${r.dominio}/api/catalog_system/pub/products/search?ft=${termino}&_from=${desde}&_to=${desde + POR_PAGINA_VTEX - 1}`,
          retailer_id: r.id, plataforma: 'vtex', dominio: r.dominio, marca_id: m.id, pagina: p, fecha,
        } });
      }
    } else if (r.plataforma === 'coto') {
      for (let p = 0; p < PAGINAS_COTO; p++) {
        out.push({ json: {
          url: `https://${r.dominio}/sitios/cdigi/categoria?Dy=1&Ntt=${termino}&Nrpp=${POR_PAGINA_COTO}&No=${p * POR_PAGINA_COTO}&format=json`,
          retailer_id: r.id, plataforma: 'coto', dominio: r.dominio, marca_id: m.id, pagina: p, fecha,
        } });
      }
    }
  }
}
return out;

// Nodo "Parsear y filtrar" — convierte las respuestas de cada sitio en filas de precio.
// Sólo se quedan productos de las marcas configuradas (Lay's, Doritos, 3D, Cheetos, Tostitos, Twistos, Pehuamar).

const MARCAS = $('Config').first().json.marcas || [];
const respuestas = $input.all();
const pedidos = $('Generar URLs').all();

// ---------- utilidades ----------
const norm = (s) => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9]/g, '');
const normEsp = (s) => ' ' + String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase()
  .replace(/[´`'’]/g, '').replace(/[^a-z0-9]+/g, ' ').trim() + ' ';
const num = (v) => { const n = typeof v === 'number' ? v : parseFloat(String(v ?? '').replace(',', '.')); return Number.isFinite(n) ? n : null; };
const r2 = (n) => (n == null ? null : Math.round(n * 100) / 100);

const porClave = {};
for (const m of MARCAS) { porClave[norm(m.id)] = m; porClave[norm(m.nombre)] = m; }
const GENERICAS = /pepsico|pepsi|fritolay|sabritas/;

function detectarMarca(marcaSitio, nombre) {
  const k = norm(marcaSitio);
  if (porClave[k]) return porClave[k];
  if (!k || GENERICAS.test(k)) {               // marca vacía o "PepsiCo": miramos el nombre
    const n = normEsp(nombre);
    for (const m of MARCAS) {
      const t = normEsp(m.nombre).trim();
      if (t === '3d' ? / 3 ?d /.test(n) : n.includes(' ' + t + ' ')) return m;
    }
  }
  return null;
}

function gramajeDesdeTexto(txt) {
  const m = String(txt || '').match(/(\d+(?:[.,]\d+)?)\s*(kgs?|kilos?|grs?|gramos|grm|g)\b/i);
  if (!m) return null;
  const v = num(m[1]);
  if (v == null) return null;
  const g = /^k/i.test(m[2]) ? v * 1000 : v;
  return g >= 5 && g <= 5000 ? g : null;
}

// ---------- VTEX (Carrefour, Jumbo, Disco, Vea, Día, ChangoMás) ----------
function parseVtex(productos, meta) {
  const filas = [];
  if (!Array.isArray(productos)) return filas;
  for (const p of productos) {
    const marca = detectarMarca(p.brand, p.productName);
    if (!marca) continue;
    for (const it of p.items || []) {
      const ean = String(it.ean || '').trim();
      const clave = /^\d{8,14}$/.test(ean) ? ean : `SKU-${meta.retailer_id}-${it.itemId}`;
      const seller = (it.sellers || []).find((s) => s.sellerDefault) || (it.sellers || [])[0] || {};
      const co = seller.commertialOffer || {};
      const precio = num(co.Price) > 0 ? num(co.Price) : null;

      // Precio "antes": algunas cadenas (ej. Cencosud) publican ListPrice en otra escala.
      // Sólo lo tomamos si es mayor al precio y menor a 3 veces el precio.
      let lista = precio;
      for (const cand of [num(co.ListPrice), num(co.PriceWithoutDiscount)]) {
        if (precio && cand && cand > precio && cand < precio * 3) lista = Math.max(lista, cand);
      }
      const teasers = [...(co.Teasers || []), ...(co.PromotionTeasers || []), ...(co.DiscountHighLight || [])]
        .map((t) => t && (t.Name || t.name || t['<Name>k__BackingField']))
        .filter(Boolean);
      const descuento = precio && lista > precio * 1.005;
      const promoTexto = teasers.length
        ? [...new Set(teasers)].join(' | ')
        : descuento ? `-${Math.round((1 - precio / lista) * 100)}% (antes $${Math.round(lista)})` : null;

      const gramaje = gramajeDesdeTexto(it.nameComplete || it.name || p.productName)
        ?? gramajeDesdeTexto((p['Contenido Neto'] || [])[0])
        ?? (/^gr/i.test((p['Gramaje de unidad de medida'] || [])[0] || '') ? num((p['Gramaje de unidad de consumo'] || [])[0]) : null);

      filas.push({
        retailer_id: meta.retailer_id,
        ean: clave,
        nombre: it.nameComplete || it.name || p.productName,
        marca: marca.nombre,
        precio: r2(precio),
        precio_lista: r2(lista),
        en_promo: Boolean(descuento || teasers.length),
        promo_texto: promoTexto,
        disponible: Boolean(co.IsAvailable) && (co.AvailableQuantity == null || co.AvailableQuantity > 0) && precio != null,
        url: p.link || (p.linkText ? `https://${meta.dominio}/${p.linkText}/p` : null),
        gramaje_g: gramaje,
        imagen_url: ((it.images || [])[0] || {}).imageUrl || null,
      });
    }
  }
  return filas;
}

// ---------- Coto Digital (Oracle Endeca, ?format=json) ----------
function buscarRegistros(obj, prof = 0) {
  if (!obj || typeof obj !== 'object' || prof > 12) return null;
  if (obj['@type'] === 'Category_ResultsList' && Array.isArray(obj.records)) return obj.records;
  for (const v of Array.isArray(obj) ? obj : Object.values(obj)) {
    const r = buscarRegistros(v, prof + 1);
    if (r) return r;
  }
  return null;
}
const parseJSONSeguro = (s, def) => { try { return JSON.parse(s); } catch (e) { return def; } };

function parseCoto(data, meta) {
  const filas = [];
  for (const rec of buscarRegistros(data) || []) {
    const r = (rec.records && rec.records[0]) || rec;
    const a = r.attributes || {};
    const g = (k) => (a[k] || [])[0];
    const nombre = g('product.displayName') || g('sku.displayName');
    const marca = detectarMarca(g('product.brand') || g('product.MARCA'), nombre);
    if (!marca) continue;

    const ean = String(g('product.eanPrincipal') || '').trim();
    const clave = /^\d{8,14}$/.test(ean) ? ean : `SKU-coto-${g('record.id')}`;
    const precio = num(g('sku.activePrice'));
    const dto = parseJSONSeguro(g('sku.dtoPrice') || '{}', {});
    let lista = precio;
    const pl = num(dto.precioLista);
    if (precio && pl && pl > precio && pl < precio * 3) lista = pl;

    const descuentos = parseJSONSeguro(g('product.dtoDescuentos') || '[]', []);
    const textos = (Array.isArray(descuentos) ? descuentos : [])
      .map((d) => d && (d.textoDescuento || d.descripcion || d.nombre || d.texto))
      .filter(Boolean);
    const descuento = precio && lista > precio * 1.005;

    const q = num(g('sku.quantity'));
    const gramaje = gramajeDesdeTexto(nombre) ?? (q && q >= 5 && q <= 5000 ? q : null);
    const estado = ((r.detailsAction || {}).recordState || '').split('?')[0];

    filas.push({
      retailer_id: meta.retailer_id,
      ean: clave,
      nombre,
      marca: marca.nombre,
      precio: r2(precio > 0 ? precio : null),
      precio_lista: r2(lista > 0 ? lista : null),
      en_promo: Boolean(descuento || textos.length),
      promo_texto: textos.length ? [...new Set(textos)].join(' | ')
        : descuento ? `-${Math.round((1 - precio / lista) * 100)}% (antes $${Math.round(lista)})` : null,
      disponible: precio > 0,
      url: estado ? `https://www.cotodigital.com.ar/sitios/cdigi/productos${estado}` : null,
      gramaje_g: gramaje,
      imagen_url: g('product.mediumImage.url') || null,
    });
  }
  return filas;
}

// ---------- recorrer respuestas ----------
const filas = [];
const vistos = new Set();
const errores = [];
const conteo = {};

for (let i = 0; i < respuestas.length; i++) {
  let meta;
  try { meta = $('Generar URLs').itemMatching(i).json; } catch (e) { meta = (pedidos[i] || {}).json; }
  if (!meta) continue;
  const res = respuestas[i].json || {};
  if (res.error) { errores.push({ url: meta.url, error: String(res.error.message || res.error).slice(0, 200) }); continue; }

  const cuerpo = res.body ?? res.data;
  const data = typeof cuerpo === 'string' ? parseJSONSeguro(cuerpo, null) : cuerpo;
  if (data == null) { errores.push({ url: meta.url, error: 'Respuesta no es JSON (posible bloqueo o página de error)' }); continue; }

  const nuevas = meta.plataforma === 'coto' ? parseCoto(data, meta) : parseVtex(data, meta);
  for (const f of nuevas) {
    const k = f.retailer_id + '|' + f.ean;
    if (vistos.has(k)) continue;
    vistos.add(k);
    filas.push(f);
    conteo[f.retailer_id] = (conteo[f.retailer_id] || 0) + 1;
  }
}

const fecha = (pedidos[0] || { json: {} }).json.fecha
  || new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Argentina/Buenos_Aires' }).format(new Date());

return [{ json: {
  fecha,
  filas,
  total: filas.length,
  por_retailer: conteo,
  errores: errores.slice(0, 30),
  cantidad_errores: errores.length,
} }];
